"""Native output checkpoints generated by this run, never release inputs."""
import copy,json
from pathlib import Path
import torch
from baseline.common import rng_state,configuration,optimizer,write
from baseline.data import configure
from utils.exact_split_branchpoint import RAW_NAMES,model_digest,digest

def save(out,m,s,c,i,is_c3vd):
    s.save(i,'fine');(out/'cfg_args').write_text(str(c))
    q=dict(iteration=i,exact_raw={k:getattr(m,k).detach().cpu().clone() for k in RAW_NAMES},optimizer=m.optimizer.state_dict(),
        model_sha256=model_digest(m),active_sh_degree=m.active_sh_degree,spatial_lr_scale=m.spatial_lr_scale,is_c3vd=is_c3vd,
        stage12=m.harmonic_nodes.payload() if hasattr(m,'harmonic_nodes') else None,
        m2={k:v.cpu() for k,v in m.stage14_ref.items()} if hasattr(m,'stage14_ref') else None,**rng_state())
    if hasattr(m,'stage11_boundary'):q.update(boundary=m.stage11_boundary.cpu(),floor=m.stage11_floor.cpu())
    torch.save(q,out/f'fine_state_{i}.pth')

def load(out,data,iteration):
    import argparse
    from scene import Scene
    from scene.gaussian_model import GaussianModel
    from utils.stage12 import HarmonicNodes
    out=Path(out);configure(data);c,groups=configuration(data,out)
    import ast
    node=ast.parse((out/'cfg_args').read_text(),mode='eval').body
    assert isinstance(node,ast.Call) and isinstance(node.func,ast.Name) and node.func.id=='Namespace'
    for item in node.keywords:setattr(c,item.arg,ast.literal_eval(item.value))
    c.source_path=str(data);c.model_path=str(out)
    lp,hp,op,pp=groups;m=GaussianModel(c.sh_degree,hp.extract(c));s=Scene(lp.extract(c),m,load_iteration=iteration,shuffle=False)
    state=torch.load(out/f'fine_state_{iteration}.pth',map_location='cpu',weights_only=False)
    with torch.no_grad():
        for k,v in state['exact_raw'].items():getattr(m,k).copy_(v.cuda())
    m.active_sh_degree=state['active_sh_degree'];m.spatial_lr_scale=state['spatial_lr_scale']
    # Native PLY loading recomputes neighbors on the trained XYZ; M2 must retain
    # the original Gaussian99 tensor generated before this run's coarse stage.
    m.closest_point_indices=torch.load(out/'setup/knn99.pth',map_location='cuda',weights_only=True)
    if state['stage12'] is not None:m.harmonic_nodes=HarmonicNodes.from_payload(state['stage12'],'cuda')
    if state['m2'] is not None:m.stage14_ref={k:v.cuda() for k,v in state['m2'].items()}
    if 'boundary' in state:m.stage11_boundary=state['boundary'].cuda();m.stage11_floor=state['floor'].cuda()
    assert model_digest(m)==state['model_sha256']
    optimizer(m,c);m.optimizer.load_state_dict(state['optimizer'])
    assert digest(m.optimizer.state_dict())==digest(state['optimizer'])
    if state['stage12'] is not None:assert digest(m.harmonic_nodes.payload())==digest(state['stage12'])
    return m,s,pp.extract(c),torch.zeros(3,device='cuda'),c,state
